"use client"

import { createColumnHelper } from "@tanstack/react-table"
import { EllipsisIcon, PencilIcon } from "lucide-react"
import { useCallback, useRef } from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  DataTableColumnHeader,
  type DataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import type { ResponsiveColumn } from "@/components/blocks/openlmis/data-table/responsive-columns"
import { StatusBadge } from "@/components/openlmis/status-badge"

import type { FacilityType } from "@/components/openlmis/facility-types-page/facility-type-form"

/** The columns the View menu lists; code and name are left out, so they always show. */
export const FACILITY_TYPE_HIDEABLE_COLUMNS: (ResponsiveColumn & {
  label: string
})[] = [
  { id: "displayOrder", label: "Display Order", hideBelow: "lg" },
  { id: "active", label: "Status", hideBelow: "md" },
]

export const FACILITY_TYPE_SORT_FIELDS = [
  "displayOrder",
  "code",
  "name",
  "active",
] as const

export type FacilityTypeSortField = (typeof FACILITY_TYPE_SORT_FIELDS)[number]

const columnHelper = createColumnHelper<DataTableFeatures, FacilityType>()

export function createFacilityTypeColumns(onEdit: (id: string) => void) {
  return columnHelper.columns([
    columnHelper.accessor("code", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Code" />
      ),
      cell: ({ getValue }) => (
        <span className="flex">
          <span className="min-w-0 truncate font-medium" dir="ltr">
            {getValue()}
          </span>
        </span>
      ),
      meta: { className: "@xl/table:w-1/3" },
    }),
    columnHelper.accessor("name", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Name" />
      ),
      cell: ({ getValue }) =>
        getValue() ? (
          <span className="flex">
            <span className="min-w-0 truncate" dir="auto">
              {getValue()}
            </span>
          </span>
        ) : (
          <span className="text-muted-foreground">-</span>
        ),
    }),
    columnHelper.accessor("displayOrder", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Display Order" />
      ),
      cell: ({ getValue }) => (
        <span className="tabular-nums">{getValue() ?? "-"}</span>
      ),
      meta: { className: "w-40" },
    }),
    columnHelper.accessor("active", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Status" />
      ),
      cell: ({ getValue }) =>
        getValue() ? (
          <StatusBadge tone="success">Active</StatusBadge>
        ) : (
          <StatusBadge tone="destructive">Inactive</StatusBadge>
        ),
      meta: { className: "w-32" },
    }),
    columnHelper.display({
      id: "actions",
      header: () => <span className="sr-only">Actions</span>,
      cell: ({ row }) => (
        <FacilityTypeActions onEdit={onEdit} type={row.original} />
      ),
      meta: { className: "w-16" },
    }),
  ])
}

/** Keeps a closing menu from taking focus back to its trigger when an item opened a dialog, which then owns focus. */
function useMenuOpensDialog() {
  const opened = useRef(false)

  const onOpenChange = useCallback((open: boolean) => {
    if (open) opened.current = false
  }, [])
  const finalFocus = useCallback(() => !opened.current, [])
  const opensDialog = useCallback(
    (open: () => void) => () => {
      opened.current = true
      open()
    },
    []
  )

  return { onOpenChange, finalFocus, opensDialog }
}

function FacilityTypeActions({
  type,
  onEdit,
}: {
  type: FacilityType
  onEdit: (id: string) => void
}) {
  const menu = useMenuOpensDialog()

  return (
    <div className="flex justify-end">
      <DropdownMenu onOpenChange={menu.onOpenChange}>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label={`Actions For ${type.name || type.code}`}
              size="icon-sm"
              variant="ghost"
            />
          }
        >
          <EllipsisIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent
          align="end"
          className="w-auto"
          finalFocus={menu.finalFocus}
        >
          <DropdownMenuGroup>
            <DropdownMenuItem onClick={menu.opensDialog(() => onEdit(type.id))}>
              <PencilIcon />
              Edit
            </DropdownMenuItem>
          </DropdownMenuGroup>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  )
}

"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { type ReactNode, useEffect, useMemo, useRef } from "react"

import { FieldGroup } from "@/components/ui/field"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogError,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogLoadError,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  FieldSkeleton,
  SkeletonLine,
} from "@/components/openlmis/form-fields/form-fields"

import {
  EMPTY_FACILITY_TYPE_FORM,
  type FacilityType,
  type FacilityTypeFormValues,
  facilityTypeFormSchema,
  type TakenFacilityType,
  toFacilityTypeFormValues,
} from "@/components/openlmis/facility-types-page/facility-type-form"

const NO_TYPES: readonly TakenFacilityType[] = []

/** `new` to create a facility type, or the id of the type to edit. */
export type FacilityTypeFormDialogTarget = "new" | (string & {})

type FacilityTypeFormDialogProps = {
  /** Opens the dialog while set. */
  target: FacilityTypeFormDialogTarget | undefined
  /** The type being edited; a skeleton shows until it is set. */
  type?: FacilityType | undefined
  /** Every type, so a code or name already taken is refused; add any the server refused. */
  types?: readonly TakenFacilityType[]
  /** The type to edit no longer exists. */
  notFound?: boolean
  /** Loading the type failed; shows the error with Try Again. */
  onRetry?: (() => void) | undefined
  /** Called with the values; save them, then clear `target` to close. */
  onSubmit: (
    values: FacilityTypeFormValues,
    type: FacilityType | undefined
  ) => void
  /** Keeps the dialog open and shows a spinner while the type is saved. */
  pending?: boolean
  /** Shown above the fields, e.g. why the save failed. */
  error?: ReactNode
  onClose: () => void
}

export function FacilityTypeFormDialog({
  target,
  type,
  types = NO_TYPES,
  notFound = false,
  onRetry,
  onSubmit,
  pending = false,
  error,
  onClose,
}: FacilityTypeFormDialogProps) {
  const { shown, dialogProps } = useDialogTarget(target, onClose)
  const isNew = shown === "new"
  const title = isNew ? "Create Facility Type" : "Edit Facility Type"
  const submitLabel = isNew ? "Create" : "Save"

  return (
    <FormDialog {...dialogProps(pending)}>
      {shown &&
        (isNew ? (
          <FacilityTypeForm
            error={error}
            key="new"
            onSubmit={onSubmit}
            pending={pending}
            types={types}
          />
        ) : notFound ? (
          <>
            <FormDialogHeader>
              <FormDialogTitle>{title}</FormDialogTitle>
              <FormDialogDescription>
                This facility type no longer exists.
              </FormDialogDescription>
            </FormDialogHeader>
            <FormDialogFooter>
              <FormDialogCancel>Close</FormDialogCancel>
            </FormDialogFooter>
          </>
        ) : onRetry ? (
          <FormDialogLoadError
            errorTitle="Could Not Load Facility Type"
            onRetry={onRetry}
            title={title}
          />
        ) : type === undefined ? (
          <FacilityTypeFormSkeleton submitLabel={submitLabel} title={title} />
        ) : (
          <FacilityTypeForm
            error={error}
            // Keyed, so opening another type starts a fresh form.
            key={type.id}
            onSubmit={onSubmit}
            pending={pending}
            type={type}
            types={types}
          />
        ))}
    </FormDialog>
  )
}

type FacilityTypeFormProps = Pick<
  FacilityTypeFormDialogProps,
  "type" | "onSubmit" | "error"
> & {
  types: readonly TakenFacilityType[]
  pending: boolean
}

function FacilityTypeForm({
  type,
  types,
  onSubmit,
  pending,
  error,
}: FacilityTypeFormProps) {
  // Keyed on the values themselves, so an equal array passed inline does not rebuild or re-check.
  const typesKey = JSON.stringify(types)
  const editingId = type?.id
  const schema = useMemo(
    () =>
      facilityTypeFormSchema(
        JSON.parse(typesKey) as TakenFacilityType[],
        editingId
      ),
    [typesKey, editingId]
  )
  const checkedKey = useRef(typesKey)

  const form = useAppForm({
    defaultValues: type
      ? toFacilityTypeFormValues(type)
      : EMPTY_FACILITY_TYPE_FORM,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => onSubmit(value, type),
  })

  // A code or name the server just refused shows its error at once, without another submit.
  useEffect(() => {
    if (checkedKey.current === typesKey) return
    checkedKey.current = typesKey
    void form.validate("change")
  }, [typesKey, form])

  return (
    <FormDialogForm onSubmit={form.handleSubmit}>
      <FormDialogHeader>
        <FormDialogTitle>
          {type ? "Edit Facility Type" : "Create Facility Type"}
        </FormDialogTitle>
        <FormDialogDescription>
          {type
            ? "Change the name, display order and settings of this type."
            : "Give the type a code, a name and its place in lists."}
        </FormDialogDescription>
      </FormDialogHeader>
      <FormDialogBody>
        <FieldGroup>
          {error && (
            <FormDialogError
              description={error}
              title="Could Not Save Facility Type"
            />
          )}
          <form.AppField name="code">
            {(field) => (
              <field.TextField
                autoComplete="off"
                description={
                  type
                    ? "The code can't be changed once the type exists."
                    : undefined
                }
                dir="ltr"
                disabled={Boolean(type)}
                label="Facility Type Code"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="name">
            {(field) => (
              <field.TextField
                autoComplete="off"
                label="Facility Type Name"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="displayOrder">
            {(field) => (
              <field.NumberField
                description="Lists show facility types from the lowest number up."
                label="Facility Type Display Order"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="active">
            {(field) => (
              <field.SwitchField
                description="Facilities can be given this type."
                label="Active"
              />
            )}
          </form.AppField>
          <form.AppField name="primaryHealthCare">
            {(field) => (
              <field.SwitchField
                description="Facilities of this type give primary health care."
                label="Primary Health Care"
              />
            )}
          </form.AppField>
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel disabled={pending} />
        <FormDialogSubmit pending={pending}>
          {type ? "Save" : "Create"}
        </FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

/** A switch row whose value is still loading, laid out like `SwitchField`. */
function SwitchSkeleton() {
  return (
    <div
      aria-hidden
      className="flex min-h-8 items-center justify-between gap-3"
    >
      <SkeletonLine width="short" />
      {/* A plain element, since Skeleton owns its corner radius and a switch is round. */}
      <div className="h-4.5 w-8 shrink-0 animate-pulse rounded-full bg-muted" />
    </div>
  )
}

/** Laid out like the form, so nothing moves when the type arrives. */
function FacilityTypeFormSkeleton({
  title,
  submitLabel,
}: {
  title: string
  submitLabel: string
}) {
  return (
    <>
      <FormDialogHeader>
        <FormDialogTitle>{title}</FormDialogTitle>
        <SkeletonLine />
      </FormDialogHeader>
      <FormDialogBody>
        <div aria-busy>
          <FieldGroup>
            <FieldSkeleton label="Facility Type Code" required />
            <FieldSkeleton label="Facility Type Name" required />
            <FieldSkeleton label="Facility Type Display Order" required />
            <SwitchSkeleton />
            <SwitchSkeleton />
          </FieldGroup>
        </div>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <FormDialogSubmit disabled>{submitLabel}</FormDialogSubmit>
      </FormDialogFooter>
    </>
  )
}

import { z } from "zod"

/** A facility type as the form reads and writes it; map your API's type onto it. */
export type FacilityType = {
  id: string
  code: string
  name: string | null
  displayOrder: number | null
  active: boolean
  primaryHealthCare: boolean
}

export type TakenFacilityType = Pick<FacilityType, "id" | "code" | "name">

const MAX_WHOLE_NUMBER = 2_147_483_647

const same = (a: string | null, b: string) =>
  a?.trim().toLowerCase() === b.trim().toLowerCase()

/** Arabic-Indic and Persian digits read as their Latin ones, so any keyboard can type a number. */
const toLatinDigits = (text: string) =>
  text.replace(/[٠-٩۰-۹]/g, (digit) => {
    const code = digit.charCodeAt(0)
    return String(code - (code >= 0x06f0 ? 0x06f0 : 0x0660))
  })

const toWholeNumber = (text: string) => Number(toLatinDigits(text.trim()))

/** Refuses a code or name another type has, ignoring case; `editingId` is the type being edited. */
export function facilityTypeFormSchema(
  types: readonly TakenFacilityType[],
  editingId?: string
) {
  const others = types.filter((type) => type.id !== editingId)
  return z.object({
    code: z
      .string()
      .trim()
      .min(1, "Enter a code.")
      .refine(
        (code) => !others.some((type) => same(type.code, code)),
        "Another facility type already has this code."
      ),
    name: z
      .string()
      .trim()
      .min(1, "Enter a name.")
      .refine(
        (name) => !others.some((type) => same(type.name, name)),
        "Another facility type already has this name."
      ),
    displayOrder: z.string().superRefine((value, context) => {
      const text = toLatinDigits(value.trim())
      if (!text)
        context.addIssue({ code: "custom", message: "Enter a display order." })
      else if (!/^[0-9]+$/.test(text))
        context.addIssue({
          code: "custom",
          message: "Enter a whole number, such as 1 or 12.",
        })
      else if (Number(text) > MAX_WHOLE_NUMBER)
        context.addIssue({
          code: "custom",
          message: "Enter a number no larger than 2147483647.",
        })
    }),
    active: z.boolean(),
    primaryHealthCare: z.boolean(),
  })
}

export type FacilityTypeFormValues = z.infer<
  ReturnType<typeof facilityTypeFormSchema>
>

export const EMPTY_FACILITY_TYPE_FORM: FacilityTypeFormValues = {
  code: "",
  name: "",
  displayOrder: "1",
  active: true,
  primaryHealthCare: false,
}

export function toFacilityTypeFormValues(
  type: FacilityType
): FacilityTypeFormValues {
  return {
    code: type.code,
    name: type.name ?? "",
    displayOrder: type.displayOrder === null ? "" : String(type.displayOrder),
    active: type.active,
    primaryHealthCare: type.primaryHealthCare,
  }
}

/** The saved type with the form's values; a saved type keeps its code. */
export function toFacilityType(
  values: FacilityTypeFormValues,
  saved?: FacilityType
): Omit<FacilityType, "id"> {
  return {
    ...saved,
    code: saved?.code ?? values.code.trim(),
    name: values.name.trim(),
    displayOrder: toWholeNumber(values.displayOrder),
    active: values.active,
    primaryHealthCare: values.primaryHealthCare,
  }
}

"use client"

import {
  type ColumnVisibilityState,
  functionalUpdate,
  type PaginationState,
  type SortingState,
  useTable,
} from "@tanstack/react-table"
import { PlusIcon, ShapesIcon } from "lucide-react"
import { useCallback, useMemo, useRef, useState } from "react"

import { Button } from "@/components/ui/button"
import {
  DataTable,
  DataTableEmpty,
  DataTablePagination,
  dataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import {
  useColumnVisibility,
  useContainerSize,
} from "@/components/blocks/openlmis/data-table/responsive-columns"
import {
  ListToolbar,
  ListToolbarEnd,
} from "@/components/blocks/openlmis/list-toolbar"
import {
  Workspace,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceIcon,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { Callout } from "@/components/openlmis/callout"
import { ColumnViewOptions } from "@/components/openlmis/column-view-options"

import { MOCK_FACILITY_TYPES } from "@/components/openlmis/facility-types-page/mock-facility-types"
import {
  createFacilityTypeColumns,
  FACILITY_TYPE_HIDEABLE_COLUMNS,
  type FacilityTypeSortField,
} from "@/components/openlmis/facility-types-page/facility-type-columns"
import {
  type FacilityType,
  type FacilityTypeFormValues,
  toFacilityType,
} from "@/components/openlmis/facility-types-page/facility-type-form"
import {
  FacilityTypeFormDialog,
  type FacilityTypeFormDialogTarget,
} from "@/components/openlmis/facility-types-page/facility-type-form-dialog"

const DEFAULT_SORT = { id: "displayOrder", desc: false }
const DEFAULT_SORTING: SortingState = [DEFAULT_SORT]

const getRowId = (type: FacilityType) => type.id

const byName = (a: FacilityType, b: FacilityType) =>
  (a.name ?? "").localeCompare(b.name ?? "", undefined, {
    sensitivity: "base",
  })

// A type with no display order sorts after those with one.
const order = (type: FacilityType) =>
  type.displayOrder ?? Number.POSITIVE_INFINITY

const COMPARE: Record<
  FacilityTypeSortField,
  (a: FacilityType, b: FacilityType) => number
> = {
  displayOrder: (a, b) => order(a) - order(b),
  name: byName,
  code: (a, b) => a.code.localeCompare(b.code),
  active: (a, b) => Number(b.active) - Number(a.active),
}

type Notice = { title: string; description: string }

/** The facility types list screen; mount it from any route, e.g. the `page.tsx` this template ships. */
export function FacilityTypesPage() {
  const [types, setTypes] = useState(MOCK_FACILITY_TYPES)
  const [sorting, setSorting] = useState(DEFAULT_SORTING)
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: 10,
  })
  const [target, setTarget] = useState<FacilityTypeFormDialogTarget>()
  const [notice, setNotice] = useState<Notice>()
  const nextId = useRef(MOCK_FACILITY_TYPES.length + 1)
  const [measureContent, contentSize] = useContainerSize<HTMLDivElement>()
  // Kept for the visit only; store it (e.g. in localStorage) to remember it across visits.
  const columnChoices = useState<ColumnVisibilityState>({})
  const columnView = useColumnVisibility(
    FACILITY_TYPE_HIDEABLE_COLUMNS,
    columnChoices,
    contentSize
  )

  // Stable, so the columns built from it keep their identity between renders.
  const openDialog = useCallback((next: FacilityTypeFormDialogTarget) => {
    setNotice(undefined)
    setTarget(next)
  }, [])
  const columns = useMemo(
    () => createFacilityTypeColumns(openDialog),
    [openDialog]
  )

  // Every type is in memory, so sorting and paging happen here.
  const sorted = useMemo(() => {
    const [sort = DEFAULT_SORT] = sorting
    const compare = COMPARE[sort.id as FacilityTypeSortField]
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts a fresh copy; toSorted needs the ES2023 lib
    return [...types].sort(
      (a, b) => (sort.desc ? -compare(a, b) : compare(a, b)) || byName(a, b)
    )
  }, [types, sorting])
  const lastPage = Math.max(
    0,
    Math.ceil(sorted.length / pagination.pageSize) - 1
  )
  const page = useMemo(
    () => ({
      ...pagination,
      pageIndex: Math.min(pagination.pageIndex, lastPage),
    }),
    [pagination, lastPage]
  )
  const data = useMemo(
    () =>
      sorted.slice(
        page.pageIndex * page.pageSize,
        (page.pageIndex + 1) * page.pageSize
      ),
    [sorted, page]
  )

  const table = useTable({
    features: dataTableFeatures,
    columns,
    data,
    getRowId,
    rowCount: sorted.length,
    manualPagination: true,
    manualSorting: true,
    enableSortingRemoval: false,
    state: {
      pagination: page,
      sorting,
      columnVisibility: columnView.visibility,
    },
    onPaginationChange: (updater) =>
      setPagination(functionalUpdate(updater, page)),
    onSortingChange: (updater) => {
      setSorting(functionalUpdate(updater, sorting))
      setPagination((current) => ({ ...current, pageIndex: 0 }))
    },
  })

  const editing = types.find((type) => type.id === target)

  const save = (
    values: FacilityTypeFormValues,
    saved: FacilityType | undefined
  ) => {
    const type = toFacilityType(values, saved)
    if (saved) {
      setTypes((current) =>
        current.map((item) =>
          item.id === saved.id ? { ...type, id: saved.id } : item
        )
      )
      setNotice({
        title: "Facility Type Saved",
        description: `Changes to ${type.name} are saved.`,
      })
    } else {
      const id = `type-${nextId.current++}`
      setTypes((current) => [...current, { ...type, id }])
      setNotice({
        title: "Facility Type Created",
        description: `${type.name} is ready to give to facilities.`,
      })
    }
    setTarget(undefined)
  }

  return (
    <Workspace>
      <WorkspaceHeader>
        <WorkspaceHeading>
          <WorkspaceIcon>
            <ShapesIcon />
          </WorkspaceIcon>
          <WorkspaceTitle>Facility Types</WorkspaceTitle>
          <WorkspaceDescription>
            Group facilities by what they are, such as health centers or
            district stores.
          </WorkspaceDescription>
        </WorkspaceHeading>
      </WorkspaceHeader>
      <WorkspaceContent>
        {/* Measured, because the room for columns depends on a sidebar as well as the window. */}
        <div
          className="flex flex-col gap-4 @4xl/main:gap-6"
          ref={measureContent}
        >
          {notice && (
            <Callout title={notice.title} tone="success">
              {notice.description}
            </Callout>
          )}
          <ListToolbar>
            <ListToolbarEnd>
              <ColumnViewOptions
                columns={FACILITY_TYPE_HIDEABLE_COLUMNS}
                onReset={columnView.onReset}
                onVisibilityChange={columnView.onVisibilityChange}
                visibility={columnView.visibility}
              />
            </ListToolbarEnd>
            <div className="w-full @2xl/toolbar:w-auto">
              <Button className="w-full" onClick={() => openDialog("new")}>
                <PlusIcon data-icon="inline-start" />
                Add Facility Type
              </Button>
            </div>
          </ListToolbar>
          <DataTable
            empty={
              <DataTableEmpty
                action={
                  <Button onClick={() => openDialog("new")}>
                    <PlusIcon data-icon="inline-start" />
                    Add Facility Type
                  </Button>
                }
                description="Facility types you add appear here."
                icon={<ShapesIcon />}
                title="No Facility Types Yet"
              />
            }
            footer={sorted.length > 0 && <DataTablePagination table={table} />}
            table={table}
          />
        </div>
      </WorkspaceContent>
      <FacilityTypeFormDialog
        onClose={() => setTarget(undefined)}
        onSubmit={save}
        target={target}
        type={editing}
        types={types}
      />
    </Workspace>
  )
}

import { FacilityTypesPage } from "@/components/openlmis/facility-types-page/facility-types-page"

// A Next.js App Router route; in any other React app, render FacilityTypesPage from your own route.
export default function Page() {
  return <FacilityTypesPage />
}
